1	import { flushSync } from "react-dom";
2	
3	import {
4	  DEFAULT_TEXT_ALIGN,
5	  DEFAULT_VERTICAL_ALIGN,
6	  getFontString,
7	  getLineHeight,
8	  isWritableElement,
9	  normalizeEOL,
10	  normalizeLink,
11	  viewportCoordsToSceneCoords,
12	} from "@excalidraw/common";
13	
14	import {
15	  convertToExcalidrawElements,
16	  embeddableURLValidator,
17	  getCommonBounds,
18	  getEmbedLink,
19	  getLineHeightInPx,
20	  makeNextSelectedElementIds,
21	  maybeParseEmbedSrc,
22	  measureText,
23	  newElementWith,
24	  newTextElement,
25	  normalizeText,
26	  wrapText,
27	} from "@excalidraw/element";
28	
29	import type { ExcalidrawElementSkeleton } from "@excalidraw/element";
30	import type {
31	  ExcalidrawElement,
32	  ExcalidrawEmbeddableElement,
33	  ExcalidrawTextElement,
34	  NonDeleted,
35	} from "@excalidraw/element/types";
36	
37	import { actionCopy, actionCut } from "../actions";
38	import { tryParseSpreadsheet } from "../charts";
39	import { parseClipboard, parseDataTransferEvent } from "../clipboard";
40	import { ImageURLToFile, SVGStringToFile } from "../data/blob";
41	import { t } from "../i18n";
42	import { isMaybeMermaidDefinition } from "../mermaid";
43	import { withBatchedUpdates } from "../reactUtils";
44	import { getShortcutKey } from "../shortcut";
45	import { scrollBoundsIntoView } from "../viewport";
46	
47	import type React from "react";
48	
49	import type {
50	  ClipboardData,
51	  ParsedDataTransferFile,
52	  PastedMixedContent,
53	} from "../clipboard";
54	import type App from "./App";
55	import type { Offsets } from "../types";
56	
57	let IS_PLAIN_PASTE = false;
58	let IS_PLAIN_PASTE_TIMER = 0;
59	let PLAIN_PASTE_TOAST_SHOWN = false;
60	
61	type AppClipboardDependencies = {
62	  getContainer: () => HTMLDivElement | null;
63	};
64	
65	/**
66	 * The clipboard: cut and copy (through their actions), and paste — the
67	 * pasted data parsed (`pasteFromClipboard`) and inserted as whatever it is
68	 * (`insertClipboardContent`): images or SVG code, elements, a Mermaid
69	 * definition, embeddable URLs, a spreadsheet (as a chart), mixed content,
70	 * or text. Pasted elements go in through `app.addElementsFromPasteOrLibrary`,
71	 * as a library item or a drop does.
72	 */
73	export class AppClipboard {
74	  constructor(
75	    private app: App,
76	    private dependencies: AppClipboardDependencies,
77	  ) {}
78	
79	  // Copy/paste
80	
81	  public onCut = withBatchedUpdates((event: ClipboardEvent) => {
82	    if (!this.app.isInteractionEnabled()) {
83	      return;
84	    }
85	    const isExcalidrawActive = this.dependencies
86	      .getContainer()
87	      ?.contains(this.app.ownerDocument.activeElement);
88	    if (!isExcalidrawActive || isWritableElement(event.target)) {
89	      return;
90	    }
91	    this.app.actionManager.executeAction(actionCut, "keyboard", event);
92	    event.preventDefault();
93	    event.stopPropagation();
94	  });
95	
96	  public onCopy = withBatchedUpdates((event: ClipboardEvent) => {
97	    if (!this.app.isInteractionEnabled()) {
98	      return;
99	    }
100	    const isExcalidrawActive = this.dependencies
101	      .getContainer()
102	      ?.contains(this.app.ownerDocument.activeElement);
103	    if (!isExcalidrawActive || isWritableElement(event.target)) {
104	      return;
105	    }
106	    this.app.actionManager.executeAction(actionCopy, "keyboard", event);
107	    event.preventDefault();
108	    event.stopPropagation();
109	  });
110	
111	  // TODO: Cover with tests
112	  private async insertClipboardContent(
113	    data: ClipboardData,
114	    dataTransferFiles: ParsedDataTransferFile[],
115	    isPlainPaste: boolean,
116	  ) {
117	    const { x: sceneX, y: sceneY } = viewportCoordsToSceneCoords(
118	      {
119	        clientX: this.app.viewport.lastPosition.x,
120	        clientY: this.app.viewport.lastPosition.y,
121	      },
122	      this.app.state,
123	    );
124	
125	    // ------------------- Error -------------------
126	    if (data.errorMessage) {
127	      this.app.setState({ errorMessage: data.errorMessage });
128	      return;
129	    }
130	
131	    // ------------------- Mixed content with no files -------------------
132	    if (dataTransferFiles.length === 0 && !isPlainPaste && data.mixedContent) {
133	      await this.addElementsFromMixedContentPaste(data.mixedContent, {
134	        isPlainPaste,
135	        sceneX,
136	        sceneY,
137	      });
138	      return;
139	    }
140	
141	    // ------------------- Spreadsheet -------------------
142	
143	    if (!isPlainPaste && data.text) {
144	      const result = tryParseSpreadsheet(data.text);
145	      if (result.ok) {
146	        this.app.setState({
147	          openDialog: {
148	            name: "charts",
149	            data: result.data,
150	            rawText: data.text,
151	          },
152	        });
153	        return;
154	      }
155	    }
156	
157	    // ------------------- Images or SVG code -------------------
158	    const imageFiles = dataTransferFiles.map((data) => data.file);
159	
160	    if (imageFiles.length === 0 && data.text && !isPlainPaste) {
161	      const trimmedText = data.text.trim();
162	      if (trimmedText.startsWith("<svg") && trimmedText.endsWith("</svg>")) {
163	        // ignore SVG validation/normalization which will be done during image
164	        // initialization
165	        imageFiles.push(SVGStringToFile(trimmedText));
166	      }
167	    }
168	
169	    if (imageFiles.length > 0) {
170	      if (this.app.isToolSupported("image")) {
171	        await this.app.insertImages(imageFiles, sceneX, sceneY);
172	      } else {
173	        this.app.setState({ errorMessage: t("errors.imageToolNotSupported") });
174	      }
175	      return;
176	    }
177	
178	    // ------------------- Elements -------------------
179	    if (data.elements) {
180	      const elements = (
181	        data.programmaticAPI
182	          ? convertToExcalidrawElements(
183	              data.elements as ExcalidrawElementSkeleton[],
184	            )
185	          : data.elements
186	      ) as readonly ExcalidrawElement[];
187	      // TODO: remove formatting from elements if isPlainPaste
188	      this.app.addElementsFromPasteOrLibrary({
189	        elements,
190	        files: data.files || null,
191	        position:
192	          this.app.editorInterface.formFactor === "desktop"
193	            ? "cursor"
194	            : "center",
195	        retainSeed: isPlainPaste,
196	        preserveFrameChildrenOrder: true,
197	      });
198	      return;
199	    }
200	
201	    // ------------------- Only textual stuff remaining -------------------
202	    if (!data.text) {
203	      return;
204	    }
205	
206	    // ------------------- Successful Mermaid -------------------
207	    if (!isPlainPaste && isMaybeMermaidDefinition(data.text)) {
208	      const api = await import("@excalidraw/mermaid-to-excalidraw");
209	      try {
210	        const { elements: skeletonElements, files = {} } =
211	          await api.parseMermaidToExcalidraw(data.text);
212	
213	        const elements = convertToExcalidrawElements(skeletonElements, {
214	          regenerateIds: true,
215	        });
216	
217	        this.app.addElementsFromPasteOrLibrary({
218	          elements,
219	          files,
220	          position:
221	            this.app.editorInterface.formFactor === "desktop"
222	              ? "cursor"
223	              : "center",
224	        });
225	
226	        return;
227	      } catch (err: any) {
228	        console.warn(
229	          `parsing pasted text as mermaid definition failed: ${err.message}`,
230	        );
231	      }
232	    }
233	
234	    // ------------------- Pure embeddable URLs -------------------
235	    const nonEmptyLines = normalizeEOL(data.text)
236	      .split(/\n+/)
237	      .map((s) => s.trim())
238	      .filter(Boolean);
239	    const embbeddableUrls = nonEmptyLines
240	      .map((str) => maybeParseEmbedSrc(str))
241	      .filter(
242	        (string) =>
243	          embeddableURLValidator(string, this.app.props.validateEmbeddable) &&
244	          (/^(http|https):\/\/[^\s/$.?#].[^\s]*$/.test(string) ||
245	            getEmbedLink(string)?.type === "video"),
246	      );
247	
248	    if (
249	      !isPlainPaste &&
250	      embbeddableUrls.length > 0 &&
251	      embbeddableUrls.length === nonEmptyLines.length
252	    ) {
253	      const embeddables: NonDeleted<ExcalidrawEmbeddableElement>[] = [];
254	      for (const url of embbeddableUrls) {
255	        const prevEmbeddable: ExcalidrawEmbeddableElement | undefined =
256	          embeddables[embeddables.length - 1];
257	        const embeddable = this.app.insertEmbeddableElement({
258	          sceneX: prevEmbeddable
259	            ? prevEmbeddable.x + prevEmbeddable.width + 20
260	            : sceneX,
261	          sceneY,
262	          link: normalizeLink(url),
263	        });
264	        if (embeddable) {
265	          embeddables.push(embeddable);
266	        }
267	      }
268	      if (embeddables.length) {
269	        this.app.store.scheduleCapture();
270	        this.app.setState({
271	          selectedElementIds: Object.fromEntries(
272	            embeddables.map((embeddable) => [embeddable.id, true]),
273	          ),
274	        });
275	      }
276	      return;
277	    }
278	
279	    // ------------------- Text -------------------
280	    this.addTextFromPaste(data.text, isPlainPaste);
281	  }
282	
283	  /**
284	   * Ctrl/Cmd+V: whether the paste event that follows is a plain one (with
285	   * Shift)
286	   */
287	  public onPasteShortcut = (event: React.KeyboardEvent | KeyboardEvent) => {
288	    IS_PLAIN_PASTE = event.shiftKey;
289	    clearTimeout(IS_PLAIN_PASTE_TIMER);
290	    // reset (100ms to be safe that we it runs after the ensuing
291	    // paste event). Though, technically unnecessary to reset since we
292	    // (re)set the flag before each paste event.
293	    IS_PLAIN_PASTE_TIMER = this.app.ownerWindow.setTimeout(() => {
294	      IS_PLAIN_PASTE = false;
295	    }, 100);
296	  };
297	
298	  public clearPlainPaste = () => {
299	    clearTimeout(IS_PLAIN_PASTE_TIMER);
300	    IS_PLAIN_PASTE_TIMER = 0;
301	    IS_PLAIN_PASTE = false;
302	  };
303	
304	  public pasteFromClipboard = withBatchedUpdates(
305	    async (event: ClipboardEvent) => {
306	      if (!this.app.isInteractionEnabled()) {
307	        return;
308	      }
309	
310	      const isPlainPaste = !!IS_PLAIN_PASTE;
311	
312	      // #686
313	      const target = this.app.ownerDocument.activeElement;
314	      const isExcalidrawActive = this.dependencies
315	        .getContainer()
316	        ?.contains(target);
317	      if (event && !isExcalidrawActive) {
318	        return;
319	      }
320	
321	      const elementUnderCursor = this.app.ownerDocument.elementFromPoint(
322	        this.app.viewport.lastPosition.x,
323	        this.app.viewport.lastPosition.y,
324	      );
325	      if (
326	        event &&
327	        (!(
328	          elementUnderCursor instanceof this.app.ownerWindow.HTMLCanvasElement
329	        ) ||
330	          isWritableElement(target))
331	      ) {
332	        return;
333	      }
334	
335	      // must be called in the same frame (thus before any awaits) as the paste
336	      // event else some browsers (FF...) will clear the clipboardData
337	      // (something something security)
338	      const dataTransferList = await parseDataTransferEvent(event);
339	
340	      const filesList = dataTransferList.getFiles();
341	
342	      const data = await parseClipboard(dataTransferList, isPlainPaste);
343	
344	      if (this.app.props.onPaste) {
345	        try {
346	          if ((await this.app.props.onPaste(data, event)) === false) {
347	            return;
348	          }
349	        } catch (error: any) {
350	          console.error(error);
351	        }
352	      }
353	
354	      await this.insertClipboardContent(data, filesList, isPlainPaste);
355	
356	      this.app.setActiveTool(
357	        { type: this.app.state.preferredSelectionTool.type },
358	        { keepSelection: true },
359	      );
360	      event?.preventDefault();
361	    },
362	  );
363	
364	  // TODO rewrite this to paste both text & images at the same time if
365	  // pasted data contains both
366	  private async addElementsFromMixedContentPaste(
367	    mixedContent: PastedMixedContent,
368	    {
369	      isPlainPaste,
370	      sceneX,
371	      sceneY,
372	    }: { isPlainPaste: boolean; sceneX: number; sceneY: number },
373	  ) {
374	    if (
375	      !isPlainPaste &&
376	      mixedContent.some((node) => node.type === "imageUrl") &&
377	      this.app.isToolSupported("image")
378	    ) {
379	      const imageURLs = mixedContent
380	        .filter((node) => node.type === "imageUrl")
381	        .map((node) => node.value);
382	      const responses = await Promise.all(
383	        imageURLs.map(async (url) => {
384	          try {
385	            return { file: await ImageURLToFile(url) };
386	          } catch (error: any) {
387	            let errorMessage = error.message;
388	            if (error.cause === "FETCH_ERROR") {
389	              errorMessage = t("errors.failedToFetchImage");
390	            } else if (error.cause === "UNSUPPORTED") {
391	              errorMessage = t("errors.unsupportedFileType");
392	            }
393	            return { errorMessage };
394	          }
395	        }),
396	      );
397	
398	      const imageFiles = responses
399	        .filter((response): response is { file: File } => !!response.file)
400	        .map((response) => response.file);
401	      await this.app.insertImages(imageFiles, sceneX, sceneY);
402	      const error = responses.find((response) => !!response.errorMessage);
403	      if (error && error.errorMessage) {
404	        this.app.setState({ errorMessage: error.errorMessage });
405	      }
406	    } else {
407	      const textNodes = mixedContent.filter((node) => node.type === "text");
408	      if (textNodes.length) {
409	        this.addTextFromPaste(
410	          textNodes.map((node) => node.value).join("\n\n"),
411	          isPlainPaste,
412	        );
413	      }
414	    }
415	  }
416	
417	  private addTextFromPaste(text: string, isPlainPaste = false) {
418	    const { x, y } = viewportCoordsToSceneCoords(
419	      {
420	        clientX: this.app.viewport.lastPosition.x,
421	        clientY: this.app.viewport.lastPosition.y,
422	      },
423	      this.app.state,
424	    );
425	
426	    const textElementProps = {
427	      x,
428	      y,
429	      strokeColor: this.app.state.currentItemStrokeColor,
430	      backgroundColor: this.app.state.currentItemBackgroundColor,
431	      fillStyle: this.app.state.currentItemFillStyle,
432	      strokeWidth: this.app.getCurrentItemStrokeWidth("text"),
433	      strokeStyle: this.app.state.currentItemStrokeStyle,
434	      roundness: null,
435	      roughness: this.app.state.currentItemRoughness,
436	      opacity: this.app.state.currentItemOpacity,
437	      text,
438	      fontSize: this.app.state.currentItemFontSize,
439	      fontFamily: this.app.state.currentItemFontFamily,
440	      textAlign: DEFAULT_TEXT_ALIGN,
441	      verticalAlign: DEFAULT_VERTICAL_ALIGN,
442	      locked: false,
443	    };
444	    const fontString = getFontString({
445	      fontSize: textElementProps.fontSize,
446	      fontFamily: textElementProps.fontFamily,
447	    });
448	    const lineHeight = getLineHeight(textElementProps.fontFamily);
449	    const LINE_GAP = 10;
450	
451	    const lines = isPlainPaste ? [text] : text.split("\n");
452	    const createTextElements = (maxTextWidth: number) => {
453	      let currentY = y;
454	      return lines.reduce((acc: ExcalidrawTextElement[], line, idx) => {
455	        const originalText = normalizeText(line).trim();
456	        if (originalText.length) {
457	          const topLayerFrame = this.app.getTopLayerFrameAtSceneCoords({
458	            x,
459	            y: currentY,
460	          });
461	
462	          let metrics = measureText(originalText, fontString, lineHeight);
463	          const isTextUnwrapped = metrics.width > maxTextWidth;
464	
465	          const text = isTextUnwrapped
466	            ? wrapText(originalText, fontString, maxTextWidth)
467	            : originalText;
468	
469	          metrics = isTextUnwrapped
470	            ? measureText(text, fontString, lineHeight)
471	            : metrics;
472	
473	          const startX = x - metrics.width / 2;
474	          const startY = currentY - metrics.height / 2;
475	
476	          const element = newTextElement({
477	            ...textElementProps,
478	            x: startX,
479	            y: startY,
480	            text,
481	            originalText,
482	            lineHeight,
483	            autoResize: !isTextUnwrapped,
484	            frameId: topLayerFrame ? topLayerFrame.id : null,
485	          });
486	          acc.push(element);
487	          currentY += element.height + LINE_GAP;
488	        } else {
489	          const prevLine = lines[idx - 1]?.trim();
490	          // add paragraph only if previous line was not empty, IOW don't add
491	          // more than one empty line
492	          if (prevLine) {
493	            currentY +=
494	              getLineHeightInPx(textElementProps.fontSize, lineHeight) +
495	              LINE_GAP;
496	          }
497	        }
498	
499	        return acc;
500	      }, []);
501	    };
502	
503	    // long texts wrap as a typed one does; wrapped to fit the view, all of
504	    // it is brought in view, too — by moving it there (as far as the view
505	    // would have to scroll), not the view
506	    const pasteWithin = (offsets: Required<Offsets>) => {
507	      const textElements = createTextElements(
508	        this.app.text.getMaxTextWidth(offsets),
509	      );
510	      const scroll =
511	        textElements.length && textElements.some((el) => !el.autoResize)
512	          ? scrollBoundsIntoView({
513	              bounds: getCommonBounds(textElements),
514	              appState: this.app.state,
515	              offsets,
516	            })
517	          : null;
518	      if (!scroll) {
519	        return textElements;
520	      }
521	      const dx = scroll.scrollX - this.app.state.scrollX;
522	      const dy = scroll.scrollY - this.app.state.scrollY;
523	      return textElements.map((element) => {
524	        const nextX = element.x + dx;
525	        const nextY = element.y + dy;
526	        // at the point it's pasted at: its center
527	        const topLayerFrame = this.app.getTopLayerFrameAtSceneCoords({
528	          x: nextX + element.width / 2,
529	          y: nextY + element.height / 2,
530	        });
531	        return newElementWith(element, {
532	          x: nextX,
533	          y: nextY,
534	          frameId: topLayerFrame ? topLayerFrame.id : null,
535	        });
536	      });
537	    };
538	    // laid out as if the stats panel weren't there, to see where it lands:
539	    // it counts only beside it
540	    const offsets = this.app.text.getTextViewportOffsets();
541	    let textElements = pasteWithin(offsets);
542	    if (textElements.length === 0) {
543	      return;
544	    }
545	    const getSelectedElementIds = () =>
546	      makeNextSelectedElementIds(
547	        Object.fromEntries(textElements.map((el) => [el.id, true])),
548	        this.app.state,
549	      );
550	
551	    if (this.app.viewport.getSideUIRect("stats")) {
552	      // selected, it's in the stats panel, which grows to show its
553	      // properties: rendered so (not captured yet), the panels are measured
554	      // as they'll be — the styles panel, too, shown then, not reserved
555	      flushSync(() => {
556	        this.app.insertNewElements(textElements);
557	        this.app.setState({ selectedElementIds: getSelectedElementIds() });
558	      });
559	      const besideOffsets = this.app.text.getTextViewportOffsets(
560	        getCommonBounds(textElements),
561	      );
562	      if (
563	        besideOffsets.left !== offsets.left ||
564	        besideOffsets.right !== offsets.right
565	      ) {
566	        // beside the stats panel, or the styles panel's not as reserved:
567	        // laid out again, as the same elements (for anyone who's seen them
568	        // rendered already)
569	        const relaid = pasteWithin(besideOffsets);
570	        const pastedIds = new Set(textElements.map((element) => element.id));
571	        textElements = textElements.map((element, index) => {
572	          const { x, y, width, height, text, autoResize, frameId } =
573	            relaid[index];
574	          return newElementWith(element, {
575	            x,
576	            y,
577	            width,
578	            height,
579	            text,
580	            autoResize,
581	            frameId,
582	          });
583	        });
584	        this.app.scene.replaceAllElements(
585	          this.app.scene
586	            .getElementsIncludingDeleted()
587	            .filter((element) => !pastedIds.has(element.id)),
588	        );
589	        this.app.insertNewElements(textElements);
590	      }
591	    } else {
592	      this.app.insertNewElements(textElements);
593	    }
594	    this.app.store.scheduleCapture();
595	    this.app.setState({ selectedElementIds: getSelectedElementIds() });
596	
597	    if (
598	      !isPlainPaste &&
599	      textElements.length > 1 &&
600	      PLAIN_PASTE_TOAST_SHOWN === false &&
601	      this.app.editorInterface.formFactor !== "phone"
602	    ) {
603	      this.app.setToast({
604	        message: t("toast.pasteAsSingleElement", {
605	          shortcut: getShortcutKey("CtrlOrCmd+Shift+V"),
606	        }),
607	        duration: 5000,
608	      });
609	      PLAIN_PASTE_TOAST_SHOWN = true;
610	    }
611	  }
612	}
