case "image": {
  context.save();
  const cacheEntry =
    element.fileId !== null
      ? renderConfig.imageCache.get(element.fileId)
      : null;
  const img = isInitializedImageElement(element)
    ? cacheEntry?.image
    : undefined;

  if (img != null && !(img instanceof Promise)) {
    if (element.roundness && context.roundRect) {
      context.beginPath();
      context.roundRect(
        0,
        0,
        element.width,
        element.height,
        getCornerRadius(Math.min(element.width, element.height), element),
      );
      context.clip();
    }

    const { x, y, width, height } = element.crop
      ? element.crop
      : {
          x: 0,
          y: 0,
          width: img.naturalWidth,
          height: img.naturalHeight,
        };

    const shouldInvertImage =
      renderConfig.theme === THEME.DARK &&
      cacheEntry?.mimeType === MIME_TYPES.svg;

    if (shouldInvertImage && isSafari) {
      const devicePixelRatio = window.devicePixelRatio || 1;
      const tempCanvas = document.createElement("canvas");
      tempCanvas.width = element.width * devicePixelRatio;
      tempCanvas.height = element.height * devicePixelRatio;
      const tempContext = tempCanvas.getContext("2d");

      if (tempContext) {
        tempContext.scale(devicePixelRatio, devicePixelRatio);
        tempContext.drawImage(
          img,
          x,
          y,
          width,
          height,
          0,
          0,
          element.width,
          element.height,
        );

        const imageData = tempContext.getImageData(
          0,
          0,
          tempCanvas.width,
          tempCanvas.height,
        );

        const data = imageData.data;

        for (let i = 0; i < data.length; i += 4) {
          data[i] = 255 - data[i];
          data[i + 1] = 255 - data[i + 1];
          data[i + 2] = 255 - data[i + 2];
        }

        tempContext.putImageData(imageData, 0, 0);
        context.drawImage(
          tempCanvas,
          0,
          0,
          tempCanvas.width,
          tempCanvas.height,
          0,
          0,
          element.width,
          element.height,
        );
      }
    } else {
      if (shouldInvertImage) {
        context.filter = DARK_THEME_FILTER;
      }

      context.drawImage(
        img,
        x,
        y,
        width,
        height,
        0 /* hardcoded for the selection box*/,
        0,
        element.width,
        element.height,

